vec4 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv); }


void main() {
  vec4 ret = vec4(0.0);
  vec2 uv = vUv;
  float rad = vRadius;

    // sample previous uFrame
    ret = texture( sampler_fc_main, vUv ).xyz*(0.8 + q3*0.1);

    // darken (decay) over uTime
    ret *= 1.00; //or try: ret -= 0.004;

ret *= max(audioLow,max(audioMid,audioHigh));


  fragColor = ret;
}

